const lib = require("vt2-vuln-lib");

// TOP-LEVEL (module-scope) dynamic require -- executes the moment this
// module is loaded, never inside any function, and never itself called by
// anything in the entrypoint. This is the VT-307a/VT-300 regression case:
// before module-load edges existed, nothing connected the entrypoint's own
// module (which loads vt2-holder via `require("vt2-holder")`) to
// vt2-holder's own <module> node, so this dynamic require's blocker was
// invisible to any entrypoint-rooted traversal -- even though loading the
// entrypoint's dependency chain genuinely executes this line at runtime,
// and it could load ANY installed module, including the separate,
// never-imported top-level vt2-vuln-lib@1.9.0 instance.
const pluginName = process.env.ADV2_050_PLUGIN;
require(pluginName);

function useHolder() {
  return lib.dangerousOp();
}

module.exports = { useHolder };
